    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        points.push(0x10000 + ((unit - 0xd800) << 10) + (next - 0xdc00));
        i += 1;
        continue;
      }
    }
    points.push(unit);
  }
  return points;
}

// Every code point CPython treats as a line boundary in str.splitlines().
const LINE_BOUNDARIES = new Set([
  0x0a, // \n
  0x0b, // \v
  0x0c, // \f
  0x0d, // \r
  0x1c, // file separator
  0x1d, // group separator
  0x1e, // record separator
  0x85, // next line
  0x2028, // line separator
  0x2029, // paragraph separator
]);

/** CPython's `str.splitlines()` (keepends=False). */
export function splitLines(str) {
  const lines = [];
  let start = 0;
  let i = 0;
  while (i < str.length) {
    const code = str.charCodeAt(i);
    if (!LINE_BOUNDARIES.has(code)) {
      i += 1;
      continue;
    }
    lines.push(str.slice(start, i));
    if (code === 0x0d && str.charCodeAt(i + 1) === 0x0a) {
      i += 2;
    } else {
      i += 1;
    }
    start = i;
  }
  if (start < str.length) {
    lines.push(str.slice(start));
  }
  return lines;
}

// Code points for which CPython's Py_UNICODE_ISSPACE() is true.
const PY_SPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85, 0xa0,
  0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007,
  0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPySpace(codePoint) {
  return PY_SPACE.has(codePoint);
}

/** CPython's `str.strip()` restricted to whitespace. */
export function pyStrip(str) {
  const points = codePoints(str);
  let lo = 0;
  let hi = points.length;
  while (lo < hi && isPySpace(points[lo])) lo += 1;
  while (hi > lo && isPySpace(points[hi - 1])) hi -= 1;
  return points.slice(lo, hi);
}

const DECIMAL_DIGIT = /^\p{Nd}$/u;

/**
 * Decimal value of a code point, or -1. CPython's int() accepts every Unicode
 * decimal digit; each Nd block is a contiguous run of ten code points, so the
 * value can be recovered by walking back to the block's zero.
