/**
 * The Python values this program needs, modelled explicitly so that `repr`
 * and DeepDiff can tell a dict from a list from an int.
 *
 * - `str`   -> JS string
 * - `int`   -> JS BigInt (Python ints are arbitrary precision)
 * - `bool`  -> JS boolean
 * - `None`  -> null
 * - `list`  -> JS Array
 * - `dict`  -> PyDict (insertion ordered, arbitrary keys)
 */

export class PyDict {
  constructor(entries = []) {
    this.map = new Map(entries);
  }

  get(key) {
    return this.map.get(key);
  }

  has(key) {
    return this.map.has(key);
  }

  set(key, value) {
    this.map.set(key, value);
    return this;
  }

  keys() {
    return [...this.map.keys()];
  }

  entries() {
    return [...this.map.entries()];
  }

  get size() {
    return this.map.size;
  }
}

export function pyDict(entries) {
  return new PyDict(entries);
}

/** Marker for `type(x)` results, so repr can print `<class 'int'>`. */
export class PyType {
  constructor(name) {
    this.name = name;
  }
}

export function isDict(value) {
  return value instanceof PyDict;
}

export function isList(value) {
  return Array.isArray(value);
}

export function isStr(value) {
  return typeof value === 'string';
}

export function isInt(value) {
  return typeof value === 'bigint';
}

export function isNumber(value) {
  return typeof value === 'bigint' || typeof value === 'number';
}

/** `type(value).__name__` */
export function typeName(value) {
  if (value === null) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'bigint') return 'int';
  if (typeof value === 'number') return 'float';
  if (typeof value === 'string') return 'str';
  if (isList(value)) return 'list';
  if (isDict(value)) return 'dict';
  return 'object';
}

export function typeOf(value) {
  return new PyType(typeName(value));
}

