/**
 * CPython's `repr()` and `str()` for the value shapes this program prints.
 */

import { codePoints } from './pystr.mjs';
import { PyDict, PyType, isDict, isList } from './pyvalue.mjs';

// Py_UNICODE_ISPRINTABLE(): everything except the Cc, Cf, Cs, Co, Cn, Zl, Zp
// and Zs categories -- with U+0020 carved back out as printable.
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

function isPrintable(codePoint) {
  if (codePoint === 0x20) {
    return true;
  }
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) {
    return false; // lone surrogate (Cs)
  }
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

function hexEscape(codePoint) {
  if (codePoint < 0x100) {
    return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  }
  if (codePoint < 0x10000) {
    return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  }
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * CPython prefers single quotes and only switches to double quotes when the
 * string contains a single quote but no double quote.
