/**
 * Python's `int(str)` conversion, including the details argparse exposes:
 * surrounding Unicode whitespace, a sign, underscore separators between
 * digits, arbitrary precision, and any Unicode decimal digit.
 */

import { decimalValue, isPySpace, pyStrip } from './pystr.mjs';

export class ValueError extends Error {}

const UNDERSCORE = 0x5f;
const PLUS = 0x2b;
const MINUS = 0x2d;

/** Convert `text` the way CPython's int() does, or throw ValueError. */
export function pyInt(text) {
  const points = pyStrip(text);
  let i = 0;
  let negative = false;

  if (i < points.length && (points[i] === PLUS || points[i] === MINUS)) {
    negative = points[i] === MINUS;
    i += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; i < points.length; i += 1) {
    const cp = points[i];
    if (cp === UNDERSCORE) {
      // Underscores are only legal between two digits.
      if (!previousWasDigit) {
        throw new ValueError();
      }
      previousWasDigit = false;
      continue;
    }
    if (isPySpace(cp)) {
      throw new ValueError();
    }
    const value = decimalValue(cp);
    if (value < 0) {
      throw new ValueError();
    }
    digits += String(value);
    previousWasDigit = true;
  }

  if (!previousWasDigit) {
    throw new ValueError();
  }

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

