/**
 * Byte-accurate stand-ins for `print`, `sys.stderr.write` and `sys.argv`.
 */

import { readFileSync } from 'node:fs';
import { basename } from 'node:path';
import { decodeSurrogateEscape, encodeSurrogateEscape } from './bytes.mjs';
import { pyStr } from './pyrepr.mjs';

function write(stream, text) {
  const bytes = encodeSurrogateEscape(text);
  try {
    writeFullySync(stream.fd, bytes);
  } catch {
    stream.write(bytes);
  }
}

function writeFullySync(fd, bytes) {
  const { writeSync } = fsSyncApi();
  let offset = 0;
  while (offset < bytes.length) {
    offset += writeSync(fd, bytes, offset, bytes.length - offset);
  }
}

let cachedFs = null;
function fsSyncApi() {
  if (cachedFs === null) {
    // eslint-disable-next-line no-undef
    cachedFs = { writeSync: globalThis.__writeSync };
  }
  return cachedFs;
}

/** `print(value)` */
export function pyPrint(value) {
  write(process.stdout, `${pyStr(value)}\n`);
}

export function stderrWrite(text) {
  write(process.stderr, text);
}

/**
 * The equivalent of CPython's `sys.argv[1:]`.
 *
 * Node decodes argv as UTF-8 with U+FFFD replacement, which loses bytes that
 * CPython keeps via surrogateescape. On Linux the untouched bytes are readable
 * from /proc/self/cmdline, so prefer those and fall back to process.argv.
 */
export function scriptArgs() {
  const expected = process.argv.length - 2;
  if (expected <= 0) {
    return [];
  }
  try {
    const raw = readFileSync('/proc/self/cmdline');
    const parts = [];
    let start = 0;
    for (let i = 0; i < raw.length; i += 1) {
      if (raw[i] === 0) {
        parts.push(raw.subarray(start, i));
        start = i + 1;
      }
    }
    if (start < raw.length) {
      parts.push(raw.subarray(start));
    }
    if (parts.length >= expected) {
      return parts.slice(parts.length - expected).map(decodeSurrogateEscape);
    }
  } catch {
    // /proc is unavailable: fall through.
  }
  return process.argv.slice(2);
}

/** `os.path.basename(sys.argv[0])`, which argparse uses as the program name. */
export function progName() {
  return basename(process.argv[1] ?? 'prog');
}

