/**
 * The slice of CPython's `difflib` that DeepDiff uses when it annotates a
 * changed multi-line string: SequenceMatcher (with autojunk) and unified_diff.
 */

export class SequenceMatcher {
  constructor(isjunk, a, b, autojunk = true) {
    this.isjunk = isjunk;
    this.a = a;
    this.b = b;
    this.autojunk = autojunk;
    this.matchingBlocks = null;
    this.opcodes = null;
    this.chainB();
  }

  /**
   * Index `b`, then purge junk and "popular" elements. Popular elements stay
   * out of the index but still count as non-junk while a match is extended --
   * that asymmetry is load-bearing for the diffs CPython produces.
   */
  chainB() {
    const b = this.b;
    const b2j = new Map();
    for (let i = 0; i < b.length; i += 1) {
      const indices = b2j.get(b[i]);
      if (indices === undefined) {
        b2j.set(b[i], [i]);
      } else {
        indices.push(i);
      }
    }

    this.bjunk = new Set();
    if (this.isjunk) {
      for (const element of [...b2j.keys()]) {
        if (this.isjunk(element)) {
          this.bjunk.add(element);
          b2j.delete(element);
        }
      }
    }

    this.bpopular = new Set();
    const n = b.length;
    if (this.autojunk && n >= 200) {
      const ntest = Math.floor(n / 100) + 1;
      for (const [element, indices] of [...b2j.entries()]) {
        if (indices.length > ntest) {
          this.bpopular.add(element);
          b2j.delete(element);
        }
      }
    }

    this.b2j = b2j;
  }

  isBJunk(element) {
    return this.bjunk.has(element);
  }

  findLongestMatch(alo, ahi, blo, bhi) {
    const { a, b, b2j } = this;
    let besti = alo;
    let bestj = blo;
    let bestsize = 0;

    let j2len = new Map();
    for (let i = alo; i < ahi; i += 1) {
      const newj2len = new Map();
      const indices = b2j.get(a[i]) ?? [];
      for (const j of indices) {
        if (j < blo) {
          continue;
        }
        if (j >= bhi) {
          break;
        }
        const k = (j2len.get(j - 1) ?? 0) + 1;
        newj2len.set(j, k);
        if (k > bestsize) {
          besti = i - k + 1;
          bestj = j - k + 1;
          bestsize = k;
        }
      }
      j2len = newj2len;
    }

    // Extend by non-junk elements (popular elements count as non-junk here).
    while (
      besti > alo &&
      bestj > blo &&
      !this.isBJunk(b[bestj - 1]) &&
      a[besti - 1] === b[bestj - 1]
    ) {
      besti -= 1;
      bestj -= 1;
      bestsize += 1;
    }
    while (
      besti + bestsize < ahi &&
      bestj + bestsize < bhi &&
      !this.isBJunk(b[bestj + bestsize]) &&
      a[besti + bestsize] === b[bestj + bestsize]
    ) {
      bestsize += 1;
    }

    // Then by junk elements adjacent to the match.
    while (
