/**
 * The subset of `argparse.ArgumentParser` this program needs: optional
 * arguments only, `--flag value` and `--flag=value`, prefix abbreviation,
 * `type=` converters, required checks, `-h/--help`, and argparse's exact
 * usage/error wording on stderr with exit status 2.
 */

import { pyPrint, progName, stderrWrite } from '../pyprim/pyio.mjs';
import { reprStr } from '../pyprim/pyrepr.mjs';

class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(message);
    this.argumentName = argumentName;
  }
}

/** argparse treats a lone `-` or a negative number as a value, not a flag. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog = null } = {}) {
    this.prog = prog ?? progName();
    this.actions = [
      { optionStrings: ['-h', '--help'], dest: 'help', isHelp: true, nargs: 0 },
    ];
  }

  addArgument(optionString, { type = null, required = false, dest = null, metavar = null } = {}) {
    const name = dest ?? optionString.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings: [optionString],
      dest: name,
      type,
      required,
      metavar: metavar ?? name.toUpperCase(),
      nargs: 1,
    });
    return this;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const flag = action.optionStrings[0];
      if (action.nargs === 0) {
        return `[${flag}]`;
      }
      const body = `${flag} ${action.metavar}`;
      return action.required ? body : `[${body}]`;
    });
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    let help = this.formatUsage();
    help += '\noptions:\n';
    const rows = this.actions.map((action) => {
      if (action.isHelp) {
        return ['  -h, --help', 'show this help message and exit'];
      }
      return [`  ${action.optionStrings[0]} ${action.metavar}`, ''];
    });
    for (const [left, text] of rows) {
      help += text ? `${left.padEnd(12)}${text}\n` : `${left}\n`;
    }
    return help;
  }

  printHelp() {
    pyPrint(this.formatHelp().replace(/\n$/, ''));
  }

  error(message) {
    stderrWrite(this.formatUsage());
    stderrWrite(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Longest-prefix lookup, matching argparse's allow_abbrev behaviour. */
  lookupOption(flag) {
    for (const action of this.actions) {
      if (action.optionStrings.includes(flag)) {
        return action;
      }
    }
    if (!flag.startsWith('--')) {
      return null;
    }
    const matches = this.actions.filter((action) =>
      action.optionStrings.some((option) => option.startsWith(flag)),
    );
    if (matches.length === 1) {
      return matches[0];
    }
    if (matches.length > 1) {
      const options = matches.map((action) => action.optionStrings[0]).join(', ');
      this.error(`ambiguous option: ${flag} could match ${options}`);
    }
    return null;
  }

  looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-' || token === '--') {
      return false;
    }
    return !NEGATIVE_NUMBER.test(token);
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  parseKnownArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) {
        namespace[action.dest] = undefined;
      }
    }

    const seen = new Set();
    const extras = [];
    let optionsEnded = false;
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (optionsEnded) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (token === '--') {
        // Everything after the first `--` is positional; with no positionals
        // declared, the separator itself is left over as well.
        optionsEnded = true;
        extras.push(token);
        i += 1;
        continue;
      }
      if (!this.looksLikeOption(token)) {
        extras.push(token);
        i += 1;
        continue;
      }

      const equals = token.indexOf('=');
      const flag = equals === -1 ? token : token.slice(0, equals);
      const inlineValue = equals === -1 ? null : token.slice(equals + 1);
      const action = this.lookupOption(flag);

      if (action === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (action.isHelp) {
        this.printHelp();
        process.exit(0);
      }

      let raw;
      if (inlineValue !== null) {
        raw = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || next === '--' || this.looksLikeOption(next)) {
          this.error(`argument ${flag}: expected one argument`);
        }
        raw = next;
        i += 1;
      }

      try {
        namespace[action.dest] = this.convert(action, raw);
      } catch (error) {
        if (error instanceof ArgumentError) {
          this.error(`argument ${flag}: ${error.message}`);
        }
        throw error;
      }
      seen.add(action.dest);
      i += 1;
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action.dest))
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  convert(action, raw) {
    if (!action.type) {
      return raw;
    }
    try {
      return action.type.convert(raw);
    } catch {
      throw new ArgumentError(action.dest, `invalid ${action.type.name} value: ${reprStr(raw)}`);
    }
  }
}

