      help += text ? `${left.padEnd(helpColumn)}${text}\n` : `${left}\n`;
    }
    return help;
  }

  printHelp() {
    stdoutWrite(this.formatHelp());
  }

  error(message) {
    stderrWrite(this.formatUsage());
    stderrWrite(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Longest-prefix lookup, matching argparse's allow_abbrev behaviour. */
  lookupOption(flag) {
    for (const action of this.actions) {
      if (action.optionStrings.includes(flag)) {
        return action;
      }
    }
    if (!flag.startsWith('--')) {
      return null;
    }
    const matches = this.actions.filter((action) =>
      action.optionStrings.some((option) => option.startsWith(flag)),
    );
    if (matches.length === 1) {
      return matches[0];
    }
    if (matches.length > 1) {
      const options = matches.map((action) => action.optionStrings[0]).join(', ');
      this.error(`ambiguous option: ${flag} could match ${options}`);
    }
    return null;
  }

  looksLikeOption(token) {
    if (!token.startsWith('-') || token === '-' || token === '--') {
      return false;
    }
    return !NEGATIVE_NUMBER.test(token);
  }

  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
