/**
 * deepdiff's report model: how a change is addressed (`root['users'][0]`) and
 * the order the categories appear in when the result is printed.
 */

import { pyRepr, SetOrdered } from '../pyprim/pyrepr.mjs';
import { PyDict, pyDict } from '../pyprim/pyvalue.mjs';

/** Render a chain of dict keys / sequence indexes as a deepdiff path. */
export function formatPath(steps) {
  let path = 'root';
  for (const step of steps) {
    path += step.kind === 'index' ? `[${step.key}]` : `[${pyRepr(step.key)}]`;
  }
  return path;
}

export function dictStep(key) {
  return { kind: 'key', key };
}

export function indexStep(index) {
  return { kind: 'index', key: index };
}

// deepdiff's TextResult seeds every category up front and drops the empty ones
// afterwards, so the printed order is this one -- not the traversal order.
const CATEGORY_ORDER = [
  'type_changes',
  'dictionary_item_added',
  'dictionary_item_removed',
  'values_changed',
  'unprocessed',
  'iterable_item_added',
  'iterable_item_removed',
  'iterable_item_moved',
  'attribute_added',
  'attribute_removed',
  'set_item_removed',
  'set_item_added',
  'repetition_change',
];

const SET_CATEGORIES = new Set([
  'dictionary_item_added',
  'dictionary_item_removed',
  'attribute_added',
  'attribute_removed',
  'set_item_removed',
  'set_item_added',
]);

/** Accumulates reports during the walk, then renders like deepdiff's result. */
export class DiffReport {
  constructor() {
    this.categories = new Map();
  }

  /** Record `path -> payload` (or just `path` for the set-shaped categories). */
  add(category, path, payload) {
    let bucket = this.categories.get(category);
    if (bucket === undefined) {
      bucket = SET_CATEGORIES.has(category) ? new SetOrdered() : pyDict();
      this.categories.set(category, bucket);
    }
    if (bucket instanceof SetOrdered) {
      bucket.add(path);
    } else {
      bucket.set(path, payload);
    }
  }

  /** The result as a dict, with deepdiff's canonical category order. */
  toDict() {
    const result = new PyDict();
    for (const category of CATEGORY_ORDER) {
      const bucket = this.categories.get(category);
      if (bucket !== undefined && bucket.size > 0) {
        result.set(category, bucket);
      }
    }
    return result;
  }

  toString() {
    return pyRepr(this.toDict());
  }
}

