/**
 * DeepDiff: a recursive comparison of two Python values that reports the same
 * categories and paths as the deepdiff package.
 */

import { splitLines } from '../pyprim/pystr.mjs';
import { pyDict, isDict, isList, isStr, isNumber, typeOf } from '../pyprim/pyvalue.mjs';
import { unifiedDiff } from '../stdlib/difflib.mjs';
import { DiffReport, dictStep, formatPath, indexStep } from './model.mjs';

/** Fill value marking "this side ran out of items", like deepdiff's sentinel. */
const MISSING = Symbol('ListItemRemovedOrAdded');

export class DeepDiff {
  constructor(t1, t2) {
    this.t1 = t1;
    this.t2 = t2;
    this.report = new DiffReport();
    this.diff(t1, t2, []);
  }

  diff(t1, t2, steps) {
    if (t1 === t2) {
      return;
    }
    if (isDict(t1) && isDict(t2)) {
      this.diffDict(t1, t2, steps);
      return;
    }
    if (isList(t1) && isList(t2)) {
      this.diffList(t1, t2, steps);
      return;
    }
    if (isStr(t1) && isStr(t2)) {
      this.diffStr(t1, t2, steps);
      return;
    }
    if (isNumber(t1) && isNumber(t2)) {
      if (t1 !== t2) {
        this.reportValueChanged(t1, t2, steps);
      }
      return;
    }
    if (typeOf(t1).name !== typeOf(t2).name) {
      this.report.add(
        'type_changes',
        formatPath(steps),
        pyDict([
          ['old_type', typeOf(t1)],
          ['new_type', typeOf(t2)],
          ['old_value', t1],
          ['new_value', t2],
        ]),
      );
      return;
    }
    this.reportValueChanged(t1, t2, steps);
  }

  diffDict(t1, t2, steps) {
    const keys1 = t1.keys();
    const keys2 = t2.keys();

    for (const key of keys2) {
      if (!t1.has(key)) {
        this.report.add('dictionary_item_added', formatPath([...steps, dictStep(key)]));
      }
    }
    for (const key of keys1) {
      if (!t2.has(key)) {
        this.report.add('dictionary_item_removed', formatPath([...steps, dictStep(key)]));
      }
    }
    for (const key of keys2) {
      if (t1.has(key)) {
        this.diff(t1.get(key), t2.get(key), [...steps, dictStep(key)]);
      }
    }
  }

  /** Ordered comparison: zip the two sequences and pad the shorter one. */
  diffList(t1, t2, steps) {
    const length = Math.max(t1.length, t2.length);
    for (let i = 0; i < length; i += 1) {
      const x = i < t1.length ? t1[i] : MISSING;
      const y = i < t2.length ? t2[i] : MISSING;
      const path = formatPath([...steps, indexStep(i)]);
      if (y === MISSING) {
        this.report.add('iterable_item_removed', path, x);
      } else if (x === MISSING) {
        this.report.add('iterable_item_added', path, y);
      } else {
        this.diff(x, y, [...steps, indexStep(i)]);
      }
    }
  }

  /**
   * Changed strings additionally carry a unified diff whenever either side is
   * multi-line, which is how deepdiff makes such changes readable.
   */
  diffStr(t1, t2, steps) {
    if (t1 === t2) {
      return;
    }
    let diffText = null;
    if (t1.includes('\n') || t2.includes('\n')) {
      const lines = unifiedDiff(splitLines(t1), splitLines(t2), { lineterm: '' });
      if (lines.length > 0) {
        diffText = lines.join('\n');
      }
    }
    this.reportValueChanged(t1, t2, steps, diffText);
  }

  reportValueChanged(t1, t2, steps, diffText = null) {
    const payload = pyDict([
      ['new_value', t2],
      ['old_value', t1],
    ]);
    if (diffText !== null) {
      payload.set('diff', diffText);
    }
    this.report.add('values_changed', formatPath(steps), payload);
  }

  toDict() {
    return this.report.toDict();
  }

  toString() {
    return this.report.toString();
  }
}

export function deepDiff(t1, t2) {
  return new DeepDiff(t1, t2);
}

