/**
 * deepdiff's `extract(obj, path)`: read a value out of a nested structure
 * using the same `root['users'][0]['name']` notation the diff reports use.
 */

import { isDict, isList } from '../pyprim/pyvalue.mjs';

export class PathExtractionError extends Error {}

/** Split `root['a'][0]` into `['a', 0]`, keeping key types apart. */
export function parsePath(path) {
  if (!path.startsWith('root')) {
    throw new PathExtractionError(`Invalid path: ${path}`);
  }
  const steps = [];
  let i = 'root'.length;

  while (i < path.length) {
    if (path[i] !== '[') {
      throw new PathExtractionError(`Invalid path: ${path}`);
    }
    i += 1;

    const quote = path[i];
    if (quote === "'" || quote === '"') {
      i += 1;
      let key = '';
      while (i < path.length && path[i] !== quote) {
        if (path[i] === '\\' && i + 1 < path.length) {
          key += path[i + 1];
          i += 2;
          continue;
        }
        key += path[i];
        i += 1;
      }
      if (path[i] !== quote) {
        throw new PathExtractionError(`Invalid path: ${path}`);
      }
      i += 1;
      steps.push({ kind: 'key', key });
    } else {
      let digits = '';
      while (i < path.length && path[i] !== ']') {
        digits += path[i];
        i += 1;
      }
      if (!/^-?\d+$/.test(digits)) {
        throw new PathExtractionError(`Invalid path: ${path}`);
      }
      steps.push({ kind: 'index', key: Number(digits) });
    }

    if (path[i] !== ']') {
      throw new PathExtractionError(`Invalid path: ${path}`);
    }
    i += 1;
  }
  return steps;
}

export function extract(obj, path) {
  let current = obj;
  for (const step of parsePath(path)) {
    if (step.kind === 'key') {
      if (!isDict(current) || !current.has(step.key)) {
        throw new PathExtractionError(`Unable to get the item at ${path}`);
      }
      current = current.get(step.key);
      continue;
    }
    if (!isList(current)) {
      throw new PathExtractionError(`Unable to get the item at ${path}`);
    }
    const index = step.key < 0 ? current.length + step.key : step.key;
    if (index < 0 || index >= current.length) {
      throw new PathExtractionError(`Unable to get the item at ${path}`);
    }
    current = current[index];
  }
  return current;
}

