 * nested structure built from two command line arguments.
 */

import { ArgumentParser } from './lib/stdlib/argparse.mjs';
import { pyInt } from './lib/pyprim/pyint.mjs';
import { pyPrint, scriptArgs } from './lib/pyprim/pyio.mjs';
import { pyDict } from './lib/pyprim/pyvalue.mjs';
import { DeepDiff, extract } from './lib/deepdiff/index.mjs';

const INT_TYPE = { name: 'int', convert: pyInt };

const parser = new ArgumentParser();
parser.addArgument('--a', { type: null, required: true });
parser.addArgument('--b', { type: INT_TYPE, required: true });
const args = parser.parseArgs(scriptArgs());

const obj = pyDict([
  [
    'users',
    [
      pyDict([
        ['name', args.a],
        ['age', args.b],
      ]),
      pyDict([
        ['name', args.a + '2'],
        ['age', args.b + 1n],
      ]),
    ],
  ],
]);

const users = obj.get('users');

const r1 = new DeepDiff(obj, obj); // 比较相同对象
pyPrint(r1.toDict());
const r2 = extract(obj, "root['users'][0]['name']"); // 提取特定路径的值
pyPrint(r2);
const r3 = extract(obj, "root['users'][1]['age']"); // 提取另一个路径的值
pyPrint(r3);
const r4 = new DeepDiff(users[0], users[1]); // 比较两个用户对象
pyPrint(r4.toDict());
const r5 = extract(obj, "root['users'][0]"); // 提取整个用户对象
pyPrint(r5);
const r6 = new DeepDiff(users, []); // 比较列表和空列表
pyPrint(r6.toDict());
const r7 = new DeepDiff(obj, pyDict([['users', []]])); // 比较修改后的对象
pyPrint(r7.toDict());
const r8 = extract(obj, "root['users']"); // 提取用户列表
pyPrint(r8);

