/**
 * String helpers that follow CPython's `str` semantics rather than JS's.
 */

/** Code points of `str`, keeping unpaired surrogates as single items. */
export function codePoints(str) {
  const points = [];
  for (let i = 0; i < str.length; i += 1) {
    const unit = str.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = str.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        points.push(0x10000 + ((unit - 0xd800) << 10) + (next - 0xdc00));
        i += 1;
        continue;
      }
    }
    points.push(unit);
  }
  return points;
}

// Every code point CPython treats as a line boundary in str.splitlines().
const LINE_BOUNDARIES = new Set([
  0x0a, // \n
  0x0b, // \v
  0x0c, // \f
  0x0d, // \r
  0x1c, // file separator
  0x1d, // group separator
  0x1e, // record separator
  0x85, // next line
  0x2028, // line separator
  0x2029, // paragraph separator
]);

/** CPython's `str.splitlines()` (keepends=False). */
export function splitLines(str) {
  const lines = [];
  let start = 0;
